import streamlit as st

from chat import get_vector_store, get_llm, ask, TOP_K


st.set_page_config(page_title="Company Policy Chatbot", page_icon="📄")
st.title("Company Policy Chatbot")
st.caption(
    "Answers come only from the ingested policy documents, "
    "generated by a local LLM running in LM Studio."
)


@st.cache_resource
def load_pipeline():
    retriever = get_vector_store().as_retriever(search_kwargs={"k": TOP_K})
    return retriever, get_llm()


def show_sources(sources):
    with st.expander(f"Retrieved passages ({len(sources)})"):
        for name, page, text in sources:
            st.markdown(f"**{name}, page {page}**")
            st.text(text)


if "messages" not in st.session_state:
    st.session_state.messages = []

for msg in st.session_state.messages:
    with st.chat_message(msg["role"]):
        st.markdown(msg["content"])
        if msg.get("sources"):
            show_sources(msg["sources"])

if question := st.chat_input("Ask about a company policy"):
    st.session_state.messages.append({"role": "user", "content": question})
    with st.chat_message("user"):
        st.markdown(question)

    with st.chat_message("assistant"):
        try:
            with st.spinner("Searching the policy documents..."):
                retriever, llm = load_pipeline()
                answer, docs = ask(question, retriever, llm, st.session_state.messages)
        except Exception as e:
            st.error(f"Could not get an answer. Is LM Studio running at http://127.0.0.1:1234? ({e})")
            st.stop()

        sources = [
            (d.metadata.get("document_name"), d.metadata.get("page"), d.page_content)
            for d in docs
        ]
        st.markdown(answer)
        if sources:
            show_sources(sources)

    st.session_state.messages.append(
        {"role": "assistant", "content": answer, "sources": sources}
    )
